alter table dm_private.exam_mock_blueprints drop constraint verified_exam_manifest;
update dm_private.exam_mock_blueprints set question_count=100,duration_seconds=7200,structure_version='niftee-2027-bdes-v1',section_manifest='{"label":"B.Des. GAT","counts":{"mcq":100}}'where exam='nift';
alter table dm_private.exam_mock_blueprints add constraint verified_exam_manifest check((exam='uceed'and question_count=57 and duration_seconds=7200 and structure_version='iitb-2027-v1'and section_manifest='{"label":"Part A","counts":{"nat":14,"msq":15,"mcq":28}}'::jsonb)or(exam='ceed'and question_count=44 and duration_seconds=3600 and structure_version='iitb-2027-v1'and section_manifest='{"label":"Part A","counts":{"nat":8,"msq":10,"mcq":26}}'::jsonb)or(exam='nift'and question_count=100 and duration_seconds=7200 and structure_version='niftee-2027-bdes-v1'and section_manifest='{"label":"B.Des. GAT","counts":{"mcq":100}}'::jsonb)or(exam='nid'and structure_version is null and section_manifest is null));

create or replace function public.upsert_nift_question_bank_runtime_batch(p_records jsonb)returns integer language plpgsql security definer set search_path=pg_catalog,dm_private as $$
declare r jsonb;v jsonb;q dm_private.bank_questions;a jsonb;m jsonb;n integer:=0;
begin if auth.role()is distinct from'service_role'then raise exception'Forbidden';end if;if jsonb_typeof(p_records)is distinct from'array'or jsonb_array_length(p_records)not between 1 and 200 then raise exception'Invalid runtime batch';end if;
 for r in select value from jsonb_array_elements(p_records)loop
  if jsonb_typeof(r)is distinct from'object'or not r?'runtime'then raise exception'Explicit runtime decision required';end if;select*into q from dm_private.bank_questions where active and external_key=r->>'externalKey'and content_sha256=r->>'contentSha256'for update;if not found or q.exam<>'nift'then raise exception'Runtime record does not match active NIFT canonical content';end if;v:=nullif(r->'runtime','null'::jsonb);
  if v is not null then
   if q.question_type<>'MCQ'or q.payload->'holds'is distinct from'[]'::jsonb or v->>'kind'<>'mcq'or v->>'prompt'is distinct from q.payload->>'prompt'or v->'context'->>'version'<>'niftee-2027-bdes-v1'or v->'context'->>'cycle'<>'2027'or v->'context'->>'exam'<>'nift'or v->'context'->>'programme'<>'bdes'or v->'key'->>'kind'<>'mcq'or v->'key'->>'sourceExternalKey'is distinct from q.external_key then raise exception'Invalid verified NIFT GAT runtime';end if;
   if(v->'marking'->>'correct')::numeric<>1 or(v->'marking'->>'wrong')::numeric<>-0.25 or(v->>'points')::numeric<>1 or(v->>'negativePoints')::numeric<>0.25 or jsonb_array_length(v->'options')<>4 or jsonb_array_length(v->'key'->'correct')<>1 then raise exception'NIFT GAT marking or answer is invalid';end if;
   if v->'options'is distinct from(select jsonb_agg(jsonb_build_object('id',option->>'key','label',coalesce(nullif(btrim(option->>'text'),''),option->>'key')))from jsonb_array_elements(q.payload->'options')option)or exists(select 1 from jsonb_array_elements_text(v->'key'->'correct')chosen where not exists(select 1 from jsonb_array_elements(v->'options')option where option->>'id'=chosen))then raise exception'NIFT GAT options or key do not match canonical identifiers';end if;
   if jsonb_typeof(v->'media')is distinct from'array'or jsonb_typeof(q.payload->'assets')is distinct from'array'or jsonb_array_length(v->'media')<>jsonb_array_length(q.payload->'assets')or(coalesce((q.payload->>'visualDependency')::boolean,false)and jsonb_array_length(v->'media')=0)then raise exception'NIFT canonical figures must be resolved';end if;
   for a in select value from jsonb_array_elements(q.payload->'assets')loop if not exists(select 1 from dm_private.bank_media_assets b where b.sha256=a->>'sha256'and b.width=(a->>'width')::integer and b.height=(a->>'height')::integer and exists(select 1 from jsonb_array_elements(v->'media')image where image->>'path'=b.storage_path and image->>'sha256'=b.sha256 and(image->>'width')::integer=b.width and(image->>'height')::integer=b.height))then raise exception'NIFT runtime figure is not verified canonical media';end if;end loop;
   for m in select value from jsonb_array_elements(v->'media')loop if not exists(select 1 from jsonb_array_elements(q.payload->'assets')asset where asset->>'sha256'=m->>'sha256')then raise exception'Unreferenced NIFT runtime figure';end if;end loop;
  end if;update dm_private.bank_questions set runtime_payload=v,objective_ready=v is not null where external_key=q.external_key;n:=n+1;
 end loop;return n;end$$;
revoke all on function public.upsert_nift_question_bank_runtime_batch(jsonb)from public,anon,authenticated;grant execute on function public.upsert_nift_question_bank_runtime_batch(jsonb)to service_role;
